const r = await Promise.allSettled([
  tools.Execute({summary:"List scaffold directory", command:"ls -la /tmp/obs-readiness /tmp/obs-readiness/leptos-tauri /tmp/obs-readiness/leptos-tauri/src-tauri 2>&1", riskLevel:"low"}),
  tools.Read({file_path:"/tmp/obs-readiness/leptos-tauri/Trunk.toml"}),
  tools.Read({file_path:"/tmp/obs-readiness/leptos-tauri/Cargo.toml"}),
  tools.Read({file_path:"/tmp/obs-readiness/leptos-tauri/src-tauri/tauri.conf.json"}),
  tools.Read({file_path:"/tmp/obs-readiness/leptos-tauri/index.html"}),
  tools.Execute({summary:"Trunk serve help", command:"trunk serve --help 2>&1", riskLevel:"low"}),
  tools.Execute({summary:"Agent-browser help", command:"agent-browser --help 2>&1; agent-browser --version 2>&1", riskLevel:"low"}),
  tools.Execute({summary:"Check port and load", command:"lsof -nP -iTCP:3141 -sTCP:LISTEN; echo port-exit=$?; uptime; sysctl -n hw.ncpu hw.memsize; cat ~/.cargo/config.toml", riskLevel:"low"}),
]);
const names=["ls","Trunk.toml","Cargo.toml","tauri.conf.json","index.html","trunk serve --help","agent-browser --help","port/load"];
r.forEach((x,i)=>text(`## ${names[i]}\n${x.status==='fulfilled'?(typeof x.value==='string'?x.value:JSON.stringify(x.value)):String(x.reason)}`));

const r = await Promise.allSettled([
  tools.Execute({summary:"List ui dir and env", command:"ls -la /tmp/obs-readiness/leptos-tauri/ui /tmp/obs-readiness/leptos-tauri/ui/src /tmp/obs-readiness/leptos-tauri/src-tauri/src /tmp/obs-readiness/logs; env | grep -i -E 'CARGO|RUSTC|SCCACHE'; ls -la ~/.cargo/shared_rust_target 2>&1 | head; du -sh ~/.cargo/shared_rust_target 2>/dev/null", riskLevel:"low"}),
  tools.Read({file_path:"/tmp/obs-readiness/leptos-tauri/ui/Trunk.toml"}),
  tools.Read({file_path:"/tmp/obs-readiness/leptos-tauri/ui/Cargo.toml"}),
  tools.Read({file_path:"/tmp/obs-readiness/leptos-tauri/ui/index.html"}),
  tools.Read({file_path:"/tmp/obs-readiness/leptos-tauri/src-tauri/Cargo.toml"}),
  tools.Execute({summary:"Tool versions", command:"trunk --version; cargo tauri --version; rustc --version; which agent-browser; agent-browser doctor 2>&1 | head -40", riskLevel:"low"}),
]);
const names=["ls/env","ui/Trunk.toml","ui/Cargo.toml","ui/index.html","src-tauri/Cargo.toml","versions"];
r.forEach((x,i)=>text(`## ${names[i]}\n${x.status==='fulfilled'?(typeof x.value==='string'?x.value:JSON.stringify(x.value)):String(x.reason)}`));

// @input: cmd <<'EOF'
cd /tmp/obs-readiness/leptos-tauri && date +%s.%N > /tmp/obs-readiness/trunk-serve.start && exec trunk serve --config ui/Trunk.toml --port 3141 --open false > /tmp/obs-readiness/trunk-serve.log 2>&1
EOF
const r = await tools.Execute({summary:"Start trunk serve in background", command: inputs.cmd, riskLevel:"medium", fireAndForget:true});
text(JSON.stringify(r));

// @input: cmd <<'EOF'
agent-browser close --all 2>&1
kill 83813; sleep 2
echo "trunk alive? $(ps -p 83813 >/dev/null && echo yes || echo no)"
echo "lsof 3141:"; lsof -nP -iTCP:3141 -sTCP:LISTEN; echo "lsof exit=$?"
echo "leftovers:"; ps -axo pid,ppid,rss,command | grep -E 'trunk|agent-browser|remote-debugging-port' | grep -v grep | cut -c1-120
echo "sessions:"; agent-browser session list 2>&1
EOF
const r = await tools.Execute({summary:"Stop trunk serve and browser sessions", command: inputs.cmd, riskLevel:"medium", timeout: 60});
text(r);

// @input: cmd <<'EOF'
cd /tmp/obs-readiness/leptos-tauri && date +%s.%N > /tmp/obs-readiness/tauri-dev.start && exec cargo tauri dev --config src-tauri/tauri.conf.json > /tmp/obs-readiness/tauri-dev.log 2>&1
EOF
const r = await tools.Execute({summary:"Start cargo tauri dev in background", command: inputs.cmd, riskLevel:"medium", fireAndForget:true});
text(JSON.stringify(r));

// @input: cmd <<'EOF'
echo "--- png dims and uniformity"; sips -g pixelWidth -g pixelHeight /tmp/obs-readiness/tauri-window.png | tail -2
python3 -c "
import zlib,struct
d=open('/tmp/obs-readiness/tauri-window.png','rb').read(); print('bytes',len(d))
"
echo "--- CGWindowList via JXA (no Screen Recording needed for owner/bounds)"
osascript -l JavaScript <<'JXA' 2>&1
ObjC.import('CoreGraphics');
var list = $.CGWindowListCopyWindowInfo($.kCGWindowListOptionOnScreenOnly | $.kCGWindowListExcludeDesktopElements, $.kCGNullWindowID);
var arr = ObjC.deepUnwrap(list);
var out = [];
for (var w of arr) { if ((w.kCGWindowOwnerName||'').indexOf('tauri')>=0 || (w.kCGWindowOwnerName||'').indexOf('readiness')>=0) out.push(JSON.stringify({owner:w.kCGWindowOwnerName,name:w.kCGWindowName,bounds:w.kCGWindowBounds,pid:w.kCGWindowOwnerPID,num:w.kCGWindowNumber,layer:w.kCGWindowLayer})); }
out.length ? out.join('\n') : 'no tauri window in CGWindowList (total windows ' + arr.length + ')';
JXA
echo "--- count windows via System Events"; osascript -e 'tell application "System Events" to tell process "src-tauri" to count windows' 2>&1
echo "--- Accessibility check (AXIsProcessTrusted via JXA)"; osascript -l JavaScript -e 'ObjC.import("ApplicationServices"); $.AXIsProcessTrusted()' 2>&1
echo "--- Screen recording check (CGPreflightScreenCaptureAccess)"; osascript -l JavaScript -e 'ObjC.import("CoreGraphics"); $.CGPreflightScreenCaptureAccess()' 2>&1
echo "--- parent chain of this shell"; p=$$; for i in 1 2 3 4 5 6; do ps -o pid,ppid,comm -p $p | tail -1; p=$(ps -o ppid= -p $p | tr -d ' '); [ "$p" = "1" ] && break; done
EOF
const r = await tools.Execute({summary:"Check window list and TCC permissions", command: inputs.cmd, riskLevel:"low", timeout: 60});
text(r);

