// @input: cmd <<'EOF'
echo "--- ffmpeg signalstats of screenshot (YAVG = mean luma 0-255)"
ffmpeg -hide_banner -loglevel info -i /tmp/obs-readiness/tauri-window.png -vf signalstats,metadata=print:key=lavfi.signalstats.YAVG:file=- -f null - 2>/dev/null | grep YAVG
ffmpeg -hide_banner -i /tmp/obs-readiness/tauri-window.png -vf signalstats,metadata=print:key=lavfi.signalstats.YMAX:file=- -f null - 2>/dev/null | grep YMAX
echo "--- CGWindowList via JXA"
osascript -l JavaScript <<'JXA' 2>&1
ObjC.import('CoreGraphics');
var list = $.CGWindowListCopyWindowInfo($.kCGWindowListOptionAll, $.kCGNullWindowID);
var arr = ObjC.deepUnwrap(list);
var out = [];
for (var i = 0; i < arr.length; i++) { var w = arr[i]; var o = String(w.kCGWindowOwnerName||''); if (o.indexOf('tauri')>=0 || o.indexOf('readiness')>=0) out.push(JSON.stringify({owner:o,name:w.kCGWindowName,bounds:w.kCGWindowBounds,pid:w.kCGWindowOwnerPID,num:w.kCGWindowNumber,layer:w.kCGWindowLayer,onscreen:w.kCGWindowIsOnscreen})); }
out.length ? out.join('\n') : 'no tauri window in CGWindowList (total ' + arr.length + ')';
JXA
echo "--- displays"; system_profiler SPDisplaysDataType 2>/dev/null | grep -E 'Resolution|Main Display|Display Type' | head
echo "--- is screen locked / session"; ioreg -n Root -d1 -a | grep -A1 CGSSession | head -4; python3 -c "print(open('/dev/null').name)" >/dev/null
echo "--- app log excerpt (stdout of tauri dev after Running)"; sed 's/\x1b\[[0-9;]*[a-zA-Z]//g' /tmp/obs-readiness/tauri-dev.log | tr '\r' '\n' | awk '/Running `/{f=1} f' | grep -v 'Building \[' | tail -5
EOF
const r = await tools.Execute({summary:"Analyze screenshot and list windows", command: inputs.cmd, riskLevel:"low", timeout: 90});
text(r);

